#include <iostream>
#include <string>

class MyInteger {
private:
    int value;

public:
    explicit MyInteger(int val) : value(val) {}

    int getValue() const { return value; }

    bool isEven() const { return isEven(value); }
    bool isOdd() const { return isOdd(value); }
    bool isPrime() const { return isPrime(value); }

    static bool isEven(int n) { return n % 2 == 0; }
    static bool isOdd(int n) { return n % 2 != 0; }
    static bool isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i * i <= n; ++i) {
            if (n % i == 0) return false;
        }
        return true;
    }

    static bool isEven(const MyInteger& obj) { return isEven(obj.getValue()); }
    static bool isOdd(const MyInteger& obj) { return isOdd(obj.getValue()); }
    static bool isPrime(const MyInteger& obj) { return isPrime(obj.getValue()); }

    bool equals(int n) const { return value == n; }
    bool equals(const MyInteger& obj) const { return value == obj.getValue(); }

    static int parseInt(const std::string& s) {
        return std::stoi(s);
    }
};

int main() {
    int val;
    if (!(std::cin >> val)) return 0;

    MyInteger mi(val);
    std::cout << "Value: " << mi.getValue() << "\n";
    std::cout << "isEven: " << (mi.isEven() ? "true" : "false") << "\n";
    std::cout << "isPrime: " << (mi.isPrime() ? "true" : "false") << "\n";

    std::string strNum = "1024";
    int parsed = MyInteger::parseInt(strNum);
    std::cout << "Parsed " << strNum << " as " << parsed << "\n";
    std::cout << "equals(1024): " << (mi.equals(parsed) ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

const double PI = 3.14159265358979323846;

class RegularPolygon {
private:
    int n;
    double side;
    double x;
    double y;

public:
    RegularPolygon() : n(3), side(1.0), x(0.0), y(0.0) {}
    RegularPolygon(int numSides, double sideLength) : n(numSides), side(sideLength), x(0.0), y(0.0) {}
    RegularPolygon(int numSides, double sideLength, double xCoord, double yCoord)
        : n(numSides), side(sideLength), x(xCoord), y(yCoord) {}

    int getN() const { return n; }
    double getSide() const { return side; }
    double getX() const { return x; }
    double getY() const { return y; }

    double getPerimeter() const { return n * side; }
    double getArea() const {
        return (n * side * side) / (4.0 * std::tan(PI / n));
    }
};

struct Location {
    int row;
    int column;
    double maxValue;
};

const int ROW_SIZE = 3;
const int COLUMN_SIZE = 4;

Location locateLargest(const double a[][COLUMN_SIZE]) {
    Location loc{0, 0, a[0][0]};
    for (int i = 0; i < ROW_SIZE; ++i) {
        for (int j = 0; j < COLUMN_SIZE; ++j) {
            if (a[i][j] > loc.maxValue) {
                loc.maxValue = a[i][j];
                loc.row = i;
                loc.column = j;
            }
        }
    }
    return loc;
}

int main() {
    RegularPolygon p1;
    RegularPolygon p2(6, 4.0);
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "P1 perimeter: " << p1.getPerimeter() << ", area: " << p1.getArea() << "\n";
    std::cout << "P2 perimeter: " << p2.getPerimeter() << ", area: " << p2.getArea() << "\n";

    double matrix[ROW_SIZE][COLUMN_SIZE] = {
        {23.5, 35.0, 2.0, 10.0},
        {4.5, 3.0, 45.0, 3.5},
        {35.0, 44.0, 5.5, 9.6}
    };

    Location loc = locateLargest(matrix);
    std::cout << "Largest element is " << loc.maxValue << " at (" << loc.row << ", " << loc.column << ")\n";
    return 0;
}
